apt install -y isc-dhcp-server && cat > /etc/dhcp/dhcpd.conf << 'EOF'
subnet 192.168.1.0 netmask 255.255.255.0 {
  range 192.168.1.100 192.168.1.200;
  option routers 192.168.1.1;
  option domain-name-servers 8.8.8.8;
}
EOF && systemctl restart isc-dhcp-server

apt install -y bind9 && cat > /etc/bind/named.conf.local << 'EOF'
zone "example.com" {
  type master;
  file "/etc/bind/db.example.com";
};
EOF && cat > /etc/bind/db.example.com << 'EOF'
$TTL 86400
@ IN SOA ns1.example.com. admin.example.com. (20240101 3600 900 604800 86400)
@ IN NS ns1.example.com.
@ IN A 192.168.1.10
www IN A 192.168.1.10
EOF && systemctl restart bind9
